// FILE: src/domains/storefront-api/cart-link.ts — THE BAG LINK (Storefront API SA1b, plan D·1; spec § 4).
//
// A brand's website sends its shopper's bag to the store's checkout with ONE URL:
//   https://<checkout host>/cart?l=<size id>:<qty>,<size id>:<qty>&code=<offer code>&utm_source=…
// A published contract with a FROZEN grammar: the URL has no version, so `l` never changes meaning; anything new is a
// new parameter. Nothing is written on a server: the page fills the shopper's own bag (localStorage) and opens checkout,
// which prices everything again and drops what can't be bought ("changed"). Limits are the quote's own (quote.ts).
// Pure: no I/O; the starter copies this file (kit/starter, held equal by a test).
// =============================================================================

const MAX_QTY = 10
const MAX_LINES = 20

export type CartLine = { variantId: string; qty: number }

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/
const LINE = /^([0-9A-Fa-f-]{36}):(\d{1,3})$/
/** The parameters a bag link carries beside `l` (the attribution island reads its own keys from the same URL). */
export const CART_PARAMS = ['l', 'code'] as const

/**
 * The bag a link names, or null when `l` is missing or malformed. Each line is a size id (any case; read lower) and a
 * quantity of 1 or more; a quantity over the quote's MAX_QTY is lowered to it, a size given twice is summed then
 * lowered, more than MAX_LINES lines refuse the link. URLSearchParams has already decoded `%3A` and `%2C`.
 */
export function parseCartLink(search: string): CartLine[] | null {
  let raw: string | null
  try { raw = new URLSearchParams(search).get('l') } catch { return null }
  if (!raw || raw.length > MAX_LINES * 41) return null
  const parts = raw.split(',')
  if (parts.length > MAX_LINES) return null
  const qty = new Map<string, number>()
  for (const part of parts) {
    const m = LINE.exec(part.trim())
    if (!m) return null
    const id = m[1]!.toLowerCase(), n = Number(m[2])
    if (!UUID.test(id) || n < 1) return null
    qty.set(id, Math.min(MAX_QTY, (qty.get(id) ?? 0) + n))
  }
  return [...qty].map(([variantId, n]) => ({ variantId, qty: n }))
}

/** A bag link for `checkoutOrigin` (`https://…`, the `shop` resource's `checkoutOrigin`), with optional extra parameters
 *  (an offer `code`, the shopper's `utm_*`). Lines past MAX_LINES are dropped; quantities are clamped to 1–MAX_QTY. */
export function cartLink(checkoutOrigin: string, lines: readonly CartLine[], extra: Readonly<Record<string, string>> = {}): string {
  const l = lines.slice(0, MAX_LINES).map((x) => `${x.variantId.toLowerCase()}:${Math.max(1, Math.min(MAX_QTY, Math.floor(x.qty)))}`).join(',')
  const q = new URLSearchParams()
  q.set('l', l)
  for (const [k, v] of Object.entries(extra)) if (k !== 'l') q.set(k, v)
  // `:` and `,` stay readable in the link (both are legal in a query); the parser accepts them encoded too.
  return `${checkoutOrigin.replace(/\/+$/, '')}/cart?${q.toString().replace(/%3A/g, ':').replace(/%2C/g, ',')}`
}
